def get_edges():
    edges = []
    # |x-y| = 1
    for x in range(1, 42):
        y = x + 1
        if y <= 42:
            edges.append((x, y))

    # |x-y| = 21
    for x in range(1, 22):
        y = x + 21
        if y <= 42:
            edges.append((x, y))

    # Sort for consistent listing
    edges.sort()
    return list(set(tuple(sorted(e)) for e in edges))

edges = get_edges()
print(f"Total number of edges: {len(edges)}")
print("Edges:")
for e in edges:
    print(e)

