verticals = []
horizontals_1 = []
horizontals_2 = []
extra = []

for x, y in edges:
    if y - x == 21:
        verticals.append((x, y))
    elif y - x == 1:
        if x <= 20:
            horizontals_1.append((x, y))
        elif x == 21:
            extra.append((x, y))
        elif x >= 22:
            horizontals_2.append((x, y))

